// AllAbbreviatedNumbers iterates over every object ListAbbreviatedNumbers lists, fetching each one with
// GetAbbreviatedNumber only when the loop reaches it. An object deleted in the meantime is skipped; on
// any other error it yields the error and stops.
func (s *Service) AllAbbreviatedNumbers(ctx context.Context, billingAccount string) iter.Seq2[*TelephonyAbbreviatedNumberGroup, error] {
	return ovh.Each(ctx,
		func(ctx context.Context) ([]int, error) {
			return s.ListAbbreviatedNumbers(ctx, billingAccount)
		},
		func(ctx context.Context, listedID int) (*TelephonyAbbreviatedNumberGroup, error) {
			return s.GetAbbreviatedNumber(ctx, billingAccount, listedID)
		})
}

